void kthread_associate_blkcg ( struct cgroup_subsys_state * css ) { struct kthread * kthread ; if ( ! ( current -> flags & PF_KTHREAD ) ) { return ; } kthread = to_kthread ( current ) ; if ( ! kthread ) { return ; } if ( kthread -> blkcg_css ) { css_put ( kthread -> blkcg_css , NULL ) ; kthread -> blkcg_css = NULL ; } if ( css ) { css_get ( css ) ; kthread -> blkcg_css = css ; } } 